self.KB_CONTENT["card:750104"]={"id":"card:750104","ty":"card","sourceId":"750104","title":"『應付憑單建立作業』中的『煙酒註記 (ACP.TA013)』為何？","ver":"iGP","topic":"應付憑單","keywords":["應付憑單","共用","註記"],"y":"other","answer":"* 預設N。* 當共用參數設定之功能別設定為「臺灣版」時，此欄位才可輸入。若為臺灣版以外版本時，此欄位不可輸入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
