self.KB_CONTENT["card:778942"]={"id":"card:778942","ty":"card","sourceId":"778942","title":"『商品包裝資料建立作業』中的『滿中箱數量 (ML006)』為何？","ver":"GP4以上","topic":"大於","keywords":["大於","包裝","商品"],"y":"other","answer":"* 是否用中箱為N時，此欄位僅作顯示。* 此欄位必須大於零。* 滿中箱重量=中箱包材淨重+(1中箱小箱數*滿小箱重量)。* 1中箱小箱數=ROUND(滿中箱數量/滿小箱數量)。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
