self.KB_CONTENT["field:783643"]={"id":"field:783643","ty":"field","sourceId":"783643","title":"選擇幣別","ver":"GP4以上","topic":"","keywords":[],"job":"客戶退票記錄明細表","code":"TC002","answer":"* 預設本國幣別，亦可修改，點選(icon)或[F2]幣別匯率查詢。* 空白表全部。進階選項","file":"fields.jsonl"};
